quests[8201] = { title = "A Collection of Heads", description = "It is true.  Hakkar now dwells in Zul'Gurub, bathing in the power of our gods.  Enthralled high priests now channel the energies of our most sacred divinities into the Soulflayer, who will soon have a strength beyond any being of Azeroth.  He must be stopped!\n\nTake this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy, as well as the head of their leader, Jin'do the Hexxer.\n\nWhen you have done this, return to me.", objectives = "String 5 Channeler's Heads and the Hexxer's Head onto the Sacred Cord, then return the Collection of Troll Heads to Exzhal on Zandalar Isle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
