quests[8273] = { title = "Oran's Gratitude", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8275] = { title = "Taking Back Silithus", description = "Attention, heroes of the Alliance!  The silithid menace has been left unchecked for too long.  Unfettered by any real opposition, they've been preparing all this time for a large-scale expansion.  \n\nCenarion Circle forces are gathering in Silithus to take the fight to these wretched creatures and all able-bodied adventurers are hereby called to join us!\n\nDon't wait until it's too late!  Aid us in the defense of Azeroth! Report to Windcaller Proudhorn at Cenarion Hold for specific instructions!", objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8276] = { title = "Taking Back Silithus", description = "Attention, champions of the Horde!  There's a threat we've left unchallenged for too long.  Tremors in the earth near silithid hives all around Azeroth have alerted us to large movements in their numbers as they prepare for expansion.\n\nCenarion Circle forces are gathering in Silithus to take the fight to the silithid before it's too late!  No more shall they defile our lands!\n\nAll able-bodied combatants are to report to Windcaller Proudhorn at Cenarion Hold!  The silithid shall be vanquished!", objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8277] = { title = "Deadly Desert Venom", description = "Beetix Ficklespragg at your service!  My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists.  Or used to, anyway.  He came back from his last trip with a strong poison running though his veins.\n\nI've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him.\n\nNoggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it.  Bring me some stingers and fangs and I'll try to make an antidote for him.", objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8278] = { title = "Noggle's Last Hope", description = "Blasted!  The antidote didn't work.  Noggle must've been stung by one of the stronger creatures in the far south.\n\nI'm going to need you to go there and get me some more samples, $N.  The good news is that since their poison is stronger I won't require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.", objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8279] = { title = "The Twilight Lexicon", description = "The Twilight's Hammer are not kind to those that leave their ranks.  They hunt me to this day like I'm some sort of beast!  Needless to say, an enemy of theirs is a friend of mine!\n\nTo decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon.  It's such an important tool that they keep its three chapters in different locations!  The officers entrusted with the Lexicon are known as Twilight Keepers, look for them at the Twilight's Hammer camps.", objectives = "Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.  ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8280] = { title = "Securing the Supply Lines", description = "Cenarion Hold is a location of utmost strategic importance.  I'm convinced that while we hold it our victory over the silithid is guaranteed.  Provided our influx supplies can be maintained, that is.\n\nDesert worms have proven to be more of a threat to our supply caravans than even the silithid themselves.  Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers.  I need you to thin their numbers to ensure our supplies aren't jeopardized.", objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8281] = { title = "Stepping Up Security", description = "Your performance has been truly exemplary so far, $N.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north.\n\nYou'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.  ", objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8282] = { title = "Noggle's Lost Satchel", description = "Where am I?  Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid.  In my rush to escape I walked right into a nest of stonelash flayers.\n\nThe satchel I was carrying had all sorts of rare reagents in it.  Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs.  I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents.\n\nI ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.", objectives = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8283] = { title = "Wanted - Deathclasp, Terror of the Sands", description = "The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity.  She presents a great threat to patrols and expeditions in the southern regions.  Individuals participating in her destruction will be remunerated handsomely.  Inquire with Captain Vish Kozus, at the top of the Cenarion Hold Watchtower, regarding a reward.", objectives = "Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8284] = { title = "The Twilight Mystery", description = "A camp of Twilight's Hammer cultists once thrived northwest of here.  If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was.\n\nI've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful.  See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus.", objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8285] = { title = "The Deserter", description = "There are rumors of a Twilight's Hammer member called Ortell having deserted his sect.  Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit.  Perhaps you can enlist his help in deciphering the tablet.\n\nTake the restored tablet with you and seek out Ortell.", objectives = "Take the restored tablet to Hermit Ortell in Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8286] = { title = "What Tomorrow Brings", description = "The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds.\n\n\"Forever you will remain if you must,\" he said, and with those words I was bound as a Watcher.\n\nLook now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed.", objectives = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8287] = { title = "A Terrible Purpose", description = "Ok, here we are... a pretty valuable chunk of information, I must say!  I've seen the Cenarion Circle forces arrive at Silithus.  They plan to drive the Twilight's Hammer out, don't they?  This will help.  \n\nTake this parchment to their leader, Commander Mar'alith.  Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!", objectives = "Take the Decoded Tablet Parchment to Commander Mar'alith.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8288] = { title = "Only One May Rise", description = "There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood.\n\nWithin the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey.", objectives = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8289] = { title = "Talismans of Merit", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8290] = { title = "Vanquish the Invaders", description = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8291] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Silverwing Talisman of Merit, and return to Sentinel Farsong at the Silverwing Grove.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8292] = { title = "Talismans of Merit", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8293] = { title = "Mark of Honor", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8294] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8295] = { title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8296] = { title = "Mark of Honor", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8297] = { title = "Arathi Basin Resources!", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8298] = { title = "More Resource Crates", description = "War must be fought with soldiers, any soldier will tell you. They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important. There are key areas in the basin that hold essential resources. Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, $N. Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8299] = { title = "Cut Arathor Supply Lines", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8300] = { title = "More Resource Crates", description = "The League of Arathor is sparing no expense in their move to retake Arathi. They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe. We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, $N. Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman. Capture and control every base you can, win the battle, and return to me with the resources you gain.", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8301] = { title = "The Path of the Righteous", description = "The Brood of Nozdormu are naturally distrusting of the lesser races. While it is true that you have proven to me that you have the potential makings of a hero, the time has come to prove this to my master.\n\nHive'Ashi, Hive'Zora, Hive'Regal: All swarming with activity and all a threat to our existence. Slay silithid at these hives and take from them a fragment of their carapace. When you can carry no more, return to me and I shall strengthen your resolve.", objectives = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8302] = { title = "The Hand of the Righteous", description = "Choose your deputies wisely, mortal. Each time you return with your task complete, a new deputy you will be allowed to choose.\n\nWith that said, I require more of the carapace fragments. Waste no time!", objectives = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8303] = { title = "Anachronos", description = "It is time, $N.\n\nI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master.", objectives = "Seek out Anachronos at the Caverns of Time in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8304] = { title = "Dearest Natalia", description = "My dear Natalia has gone missing.\n\nTruth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research.\n\nShe was last seen heading to Bronzebeard's camp to the south.\n\nMy soldiers are spread too thin, $N. I need you to go to Bronzebeard's camp and question those dwarves. ", objectives = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.\n\nOnce you have gathered the requested information, return to Commander Mar'alith.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8305] = { title = "Long Forgotten Memories", description = "In the southern desert of Silithus, near the sacred barrier, exists a single crystalline tear. This tear serves as a symbol of the great losses beset upon us during the War of the Shifting Sands. Locate this tear and gaze into its depths to gain enlightenment.", objectives = "Locate the Crystalline Tear in Silithus and gaze into its depths.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8306] = { title = "Into The Maw of Madness", description = "I need you to venture into Hive'Regal and find what became of my dearest Natalia, $N. This will be no easy task for you to do alone. I recommend that you bring some friends along. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves. They might be able to give you some tips on dealing with the silithid that inhabit that hive.\n\nAnd $N, if she truly is as mad as they say... do what you must.\n\n<Commander Mar'alith turns away from you.>", objectives = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.\n\nDo not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.\n\nAnd $N, remember the Commander's words: \"Do what you must...\"", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8307] = { title = "Desert Recipe", description = "Adapting to life in the desert has been difficult to say the least.  Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment.  I'm trying to learn about desert herbs, but there aren't many.\n\nI've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food.  Sandworm meat is so bitter though, I can't imagine how they make it palatable.  Keep your eyes open if you go to their camp and let me know if you learn anything.", objectives = "Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8308] = { title = "Brann Bronzebeard's Lost Letter", description = "To Whom It May Concern:\n\nIf you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow.\n\nFound information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it.\n\nTake this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs.\n\n-Brann Bronzebeard, Explorer Extreme\n\nP.S. Watch out for crazy Old God worshipping night elf.", objectives = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8309] = { title = "Glyph Chasing", description = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.\n\nWe must get a rubbing from crystals in all three hives. If we can get those rubbings, we might be able to make sense of this madness.\n\nTake this transcription set and some buddies and hit those hives, $N. Don't come back until you've gotten copies from each hive.", objectives = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.\n\nUse the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8310] = { title = "Breaking the Code", description = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! What do I need? Glad you asked! I need brains! More specifically, a brain from each silithid type that inhabit the hives. Bring me brains and Rutgar's work might not be for naught.", objectives = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8311] = { title = "Hallow's End Treats for Jesper!", description = "I want to go trick-or-treating, but I can't because I'm sick.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a little gnome named Talvash in Ironforge is handing out candy as well.  When you have all the candy, bring them back to me here!", objectives = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8312] = { title = "Hallow's End Treats for Spoops!", description = "I want to go trick-or-treating, but I can't because I'm sick.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a troll named Kali Remik in Sen'jin Village is handing out candy as well.  When you have all the candy, bring them back to me here!", objectives = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8313] = { title = "Sharing the Knowledge", description = "While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of.  Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.  ", objectives = "Bring the Torn Recipe Page to Calandrath at the inn in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8314] = { title = "Unraveling the Mystery", description = "We're on the verge of a breakthrough, $N! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.\n\nUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.\n\nTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.", objectives = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8315] = { title = "The Calling", description = "The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon. Above the glyphs is what I can only assume to be a code of some sort. This code might very well be the key to summoning the emissary.\n\nI will create a copy of the glyph code that you must use in the sand at the Bones of Grakkarond. If I am right, the Overlords will come thinking that new data is ready for transmission. Strike them down and confront the emissary. He holds the key to the crystals...", objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.\n\nYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.\n\nAssemble an army for this task, $N!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8316] = { title = "Armaments of War", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8317] = { title = "Kitchen Assistance", description = "That recipe sure will come in handy.  I'd better get to work so I can have some smoked desert dumplings ready for today.  I could use a hand in making some, I'll make it worth your while.", objectives = "Calandrath at Cenarion Hold needs a batch of 10 Smoked Desert Dumplings.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8318] = { title = "Secret Communication", description = "Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them.  I want you to bring me a stack of them, $c.\n\nI can't figure out what the gibberish means, but that's not the point!  These papers are how their different groups communicate secretly.  The more texts we take out of circulation, the less they can communicate!", objectives = "Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8319] = { title = "Encrypted Twilight Texts", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8320] = { title = "Twilight Geolords", description = "The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night.  We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert.\n\nAlthough their mystery may one day be solved, we must first deal with their immediate threat.  Go to their camps to the west and seek out Twilight geolords.  They are the heads of these serpents; that is where we must strike!", objectives = "Kill 10 Twilight Geolords, then return to Huum Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8321] = { title = "Vyral the Vile", description = "We have discovered another base of operations for the Twilight's Hammer.  It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring.\n\nFortune to you, $N.  The horrors of Twilight's Run are formidable indeed.", objectives = "Bring Vyral's Signet Ring to Huum Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8322] = { title = "Rotten Eggs", description = "The humans of Southshore love their ale, and as such they prize the ale served at the Southshore Inn.  With the chaos of Hallow's End now upon them, we can use it to ruin their latest batch of beverages for weeks - if not months to come!\n\nTake these rotten eggs and place them in the main brew keg inside the Southshore Inn.  Your presence alone will cause strife, so be prepared to defend yourself!\n\nOnce you've given Southshore a taste they'll not soon forget, return to me here at the festival!", objectives = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8323] = { title = "True Believers", description = "Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you.\n\nMy former organization has a secret encoded bulletin they circulate on a monthly basis.\n\nIf they make any progress searching for me or if they call off the search, word will be published on the True Believer.\n\nAlthough this information is obviously valuable to me, the publication contains other useful information that I can share.  Bring me any encoded texts you find on Twilight's Hammer members.", objectives = "Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8324] = { title = "Still Believing", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8331] = { title = "Aurel Goldleaf", description = "$N, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken.  Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps.  Your next action, $N, will be against the Abyssal Council.\n\nSpeak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold.  Her skill will be needed for this next gambit.", objectives = "Speak with Aurel Goldleaf in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8332] = { title = "Dukes of the Council", description = "We think it is possible to use a wind stone to ambush a duke of the Abyssal Council.  To do this, however, one must commune through the wind stone, and convince the council you are a middle ranked leader of the Twilight's Hammer.  \n\nSuch a gambit requires a replica of the cult's medallion of station.  I can create the medallion, but I will need a large brilliant shard, and crests worn by the Abyssal Templar.\n\nBring these to me and I will do the rest.", objectives = "Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8333] = { title = "Medallion of Station", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8341] = { title = "Lords of the Council", description = "Lords of the Abyssal Council can only be summoned through the greater wind stones, and only the top ranking members of the Twilight's Council may speak to them.  But... I have found a way to upgrade your disguise and fool the Abyssal Lords!\n\nThe disguise calls for a ring of lordship, worn only by the highest members of the cult.  I will craft one for you if you can bring me large brilliant shards and abyssal signets.", objectives = "Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8342] = { title = "Twilight Ring of Lordship", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8343] = { title = "Goldleaf's Discovery", description = "$N, Aurel Goldleaf thinks she's found a way to summon and defeat a ruling member of the Abyssal Council!  Such a task will be dangerous, but you have earned great respect amongst the Cenarion Circle.  We know that if anyone can do it, you can.\n\nMay fortune go with you, $N.  Speak with Aurel when you are ready.", objectives = "Speak with Aurel Goldleaf in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8348] = { title = "Signet of the Dukes", description = "Huum tells me you've figured out how to summon the Abyssal Dukes!  That's quite an accomplishment.\n\nYou know what else would be quite the accomplishment?  Smashing up one of those things really good.  That'll cause an impression on their underlings, if you know what I mean.  Bring back its signet as proof of the deed.", objectives = "Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8349] = { title = "Bor Wildmane", description = "Now that you have a medallion and can summon an Abyssal Duke, speak with Bor Wildmane.  He will set you on a task against the Abyssal Council.\n\nGood luck, $N.  And if you ever need more medallions, return to me.", objectives = "Speak with Bor Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8351] = { title = "Bor Wishes to Speak", description = "Now that you can disguise yourself as a ruling member of the Twilight Council, I am certain Bor Wildmane will want to speak with you.  Go see him, and prepare yourself for a very difficult mission...", objectives = "Speak with Bor Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8352] = { title = "Scepter of the Council", description = "Huum and I were just talking about you.  He tells me you're just about ready to try your hand at fighting an Abyssal Lord!\n\nI must tell you this is a very dangerous endeavor.  You'd better bring backup.  And I don't mean one or two of your friends, I'm talking about a top-notch, battle-ready fighting force.  If your friends are as good as you, you might even defeat it!\n\nIf you do - and I'll want evidence, as always - I'll give you a truly great reward.", objectives = "Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8353] = { title = "Chicken Clucking for a Mint", description = "Ah, trick-or-treating for a sick child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Ironforge Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell $c, are you up to the challenge or not?!  Time to earn your treat!", objectives = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8354] = { title = "Chicken Clucking for a Mint", description = "Ah, trick-or-treating for a sick child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Undercity Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell $c, are you up to the challenge or not?!  Time to earn your treat!", objectives = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8355] = { title = "Incoming Gumdrop", description = "A trick-or-treater!  Huzzah!\n\nWell now, even though you're doing something noble and collecting candies for a sick child, I can't let you off the hook that easily.  I have a yummy Gnomeregan Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, $c!", objectives = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8356] = { title = "Flexing for Nougat", description = "That's an... interesting costume you have on.  Even though you're being nice and helping a sick child trick-or-treat this year, I'm afraid I'm going to have to ask you perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong $g man : woman;!\n\nWhen and only when you flex, I'll give you some tasty Stormwind Nougat.  It's a great Hallow's End treat.", objectives = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8357] = { title = "Dancing for Marzipan", description = "Even though you're trick-or-treating for a sick child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!", objectives = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8358] = { title = "Incoming Gumdrop", description = "A trick-or-treater!  Yeah mon!\n\nWell now, even though you're doing something noble and collecting candies for a sick child, I can't let you off the hook that easily.  I have a yummy Darkspear Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, $c!", objectives = "Do a train emote at Kali Remik, and in exchange you'll receive a Darkspear Gumdrop!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8359] = { title = "Flexing for Nougat", description = "That's an... interesting costume you have on.  Even though you're being nice and helping a sick child trick-or-treat this year, I'm afraid I'm going to have to ask you perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong $g man : woman;!\n\nWhen and only when you flex, I'll give you some tasty Orgrimmar Nougat.  It's a great Hallow's End treat.", objectives = "Do a flex emote at Innkeeper Gryshka, and in exchange you'll receive Orgrimmar Nougat!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8360] = { title = "Dancing for Marzipan", description = "Even though you're trick-or-treating for a sick child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!", objectives = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8361] = { title = "Abyssal Contacts", description = "We've seen the Twilight's Hammer cultists performing rituals to summon powerful elemental nobles.  We don't know if these are the beings the cultists worship or if they act as intermediaries to even more powerful forces.  One thing is for sure: they are receiving orders from these elementals.\n\nI want you to find a way to contact an Abyssal Templar and give it a proper beating!  Nothing throws the troops in disarray like taking out the chain of command.  Bring back proof while you're at it.", objectives = "Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8362] = { title = "Abyssal Crests", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8363] = { title = "Abyssal Signets", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8364] = { title = "Abyssal Scepters", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8365] = { title = "Pirate Hats Ahoy!", description = "You're the help the Cartel sent? I suppose you'll do. Listen carefully $c. As you know, I am a procurer of fashionable apparel for the elite of Azerothian society.  Kings and Queens, Warchiefs and, well whatever the Horde calls their queens, all wear what I choose is in style.  And they pay through the nose for it, which is the best part.\n\nSo here's what's going to happen. You head down to Lost Rigger Cove and acquire a lot of pirate hats by whatever means. Do you think you can handle that?", objectives = "Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8366] = { title = "Southsea Shakedown", description = "Argh! They want the impossible from me!\n\nThe Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can't be in two places at once; I need to stay here to keep the peace.\n\nOf late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I'd like to temporarily deputize you to go down there and show them what for.\n\nYou'll find them at Lost Rigger Cove, which is not too far to the south.  Thanks $N, I'll owe you one!", objectives = "Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8367] = { title = "For Great Honor", description = "Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance in Arathi Basin, Alterac Valley and Warsong Gulch!  For Honor!  For the Horde!", objectives = "Bring 3 Alterac Valley Marks of Honor, 3 Arathi Basin Marks of Honor and 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8368] = { title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!", objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8369] = { title = "Invaders of Alterac Valley", description = "Listen up, $N.  No matter what you might have heard about the battle raging in Alterac Valley, one thing remains true: the Stormpike Expedition invaded Frostwolf Territory.  The day we allow the Alliance to invade Horde lands without a forceful response is the day I hang up my axe and live the rest of my life in shame.  Go forth and expel the invaders!", objectives = "Bring 3 Alterac Valley Marks of Honor to a Horde Warbringer outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8370] = { title = "Conquering Arathi Basin", description = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!", objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8371] = { title = "Concerted Efforts", description = "We're not fighting isolated battles against the Horde anymore, $g lad:lass;.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, losing any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  $N, come back to me after you've served against the Horde at all of our active battlegrounds.", objectives = "Bring 3 Alterac Valley Mark of Honor, 3 Arathi Basin Mark of Honor and 3 Warsong Gulch Mark of Honor to an Alliance Brigadier General outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8372] = { title = "Fight for Warsong Gulch", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, $N!  For the Alliance!", objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8373] = { title = "The Power of Pine", description = "The thing I hate the most about Hallow's End are the stink bombs the Forsaken use on Southshore.  Who knew that celebrating liberation would have to involve such a smelly mess?\n\nDuring Hallow's End, use this cleaner to remove any nasty stink bombs the Horde may drop here in the village.  It uses the power of pine to fight funky smells.\n\nDo your part to keep Southshore clean, and I'll give you some Hallow's End treats I'm sure you'll enjoy.  We have a deal?", objectives = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore.  Return to Sergeant Hartman in Southshore when you're done.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8374] = { title = "Claiming Arathi Basin", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $N.", objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8375] = { title = "Remember Alterac Valley!", description = "Make no mistake about it, $N.  The Horde is quite right when they say Alterac Valley is Frostwolf Territory.\n\nYou see, the Stormpike Expedition arrived as peaceful visitors to the area in search of ore and relics.  The Frostwolves reacted with the most brutal and uncivilized act of aggression the Alliance has experienced.\n\nLet us never forget the brave dwarves that perished in that cowardly unannounced attack.  Go now, $c, do your part in the battle for Alterac Valley.  For the Alliance!", objectives = "Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
