quests[8393] = { title = "Claiming Arathi Basin", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $N.", objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
