quests[8409] = { title = "Ruined Kegs", description = "The rotten eggs have been successfully placed inside the keg.  Future batches of ale from the Southshore Inn are sure to be ruined!\n\nYou should now report back to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade and report your success.", objectives = "Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8410] = { title = "Elemental Mastery", description = "Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready.\n\nTo find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.", objectives = "Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8411] = { title = "Mastering the Elements", description = "Welcome, mon.  You bring me the elements and then we do the talkin'.", objectives = "Bring the elements earth, air, fire and water to Bath'rah the Windwatcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8412] = { title = "Spirit Totem", description = "The elemental spirits of this place don't be likin' me any more.\n\nYou know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal.\n\nIn the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one.", objectives = "Bring the pieces for the spirit totem to Bath'rah the Windwatcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8413] = { title = "Da Voodoo", description = "The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.\n\nThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.", objectives = "Bring the voodoo feathers to Bath'rah the Windwatcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8414] = { title = "Dispelling Evil", description = "Greetings, $c.  Crusaders like you are a welcome sight in these desolate reaches.\n\nYour holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here.\n\nOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already.", objectives = "Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8415] = { title = "Chillwind Point", description = "Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, $n.  You can find him at Chillwind Point in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!", objectives = "Speak to Commander Ashlam Valorfist at Chillwind Point.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8416] = { title = "Inert Scourgestones", description = "The evil has been purged from the stones, $n.\n\nI am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire.", objectives = "Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8417] = { title = "A Troubled Spirit", description = "In the Blasted Lands, there is a troubled spirit who was once a great hero of the horde.  A warrior's honor does not die with the body, and it would serve you well to speak with him.", objectives = "Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8418] = { title = "Forging the Mightstone", description = "Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, $n.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.\n\nIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.", objectives = "Bring the voodoo feathers to Ashlam Valorfist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8419] = { title = "An Imp's Request", description = "$n, an imp in Felwood by the name of Impsy has requested your presence.  It is somewhat strange, as he has asked that you bring a piece of felcloth as a sign of good faith.  Considering the power you already wield as a warlock, I can only assume you know the satyrs of Felwood carry this felcloth.\n\nYou can find Impsy just north of the Bloodvenom Falls, which I've heard is quite lovely this time of year.", objectives = "Bring a piece of felcloth to Impsy in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8420] = { title = "Hot and Itchy", description = "Maybe this sounds strange coming from an imp, but I'd like a pet of my own.  I really would.  It's just not fair that Niby gets me and I get nothing!\n\nIn fact, it doesn't even need to be a living pet.  I'd need something to start making it with, like some felcloth.  The satyrs here in Felwood sometimes have felcloth, so you'd just have to kill enough of them until you find some.  That doesn't sound so bad, does it?", objectives = "Bring a piece of felcloth to Impsy in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8421] = { title = "The Wrong Stuff", description = "Now that I have my felcloth, I can really begin making *my* pet.\n\nIt's going to need some eyes though.  Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes.  They're up north in the Irontree Woods.\n\nI'll also need some bloodvenom essence to give it that new demon smell.  The tainted oozes carry the essence, and they hang out right here near Niby and me.", objectives = "Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8422] = { title = "Trolls of a Feather", description = "My pet is almost done.  Now I just need something to stuff it with.\n\nOnly the voodoo feathers from the trolls in the sunken temple will do.  They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Kill them.  Kill them all.\n\nThis is no trivial task $n, so I'll make it worth your while by giving you something of Niby's -- he probably doesn't need it anyhow.", objectives = "Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8423] = { title = "Warrior Kinship", description = "<The Hero looks you over.>\n\nYou are a $c, no doubt.  I would ask an honorable task of you, but I must test your strength.\n\nIt is said that Rexxar would measure the sharpness of his blades by killing a helboar with a single, swift strike.  Now I will measure your strength by killing them.", objectives = "Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8424] = { title = "War on the Shadowsworn", description = "The continued presence of the shadowsworn in the Blasted Lands bring great pain to me.  Their dark rituals and spells cause agony unlike any I felt while alive.\n\nThrough you I can deliver my own message of pain.  Go forth and deliver my wrath.", objectives = "Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8425] = { title = "Voodoo Feathers", description = "Your honor has brought some peace to me.  It is only right that I offer you something in return.\n\nMy weapons and armor were splendid in life, and yet they are of no use to me now.  They would be better served in your possession.\n\nTravel to the sunken temple and destroy the troll guardians Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  They carry magic feathers that can reform my physical body long enough to grant you a reward.", objectives = "Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8426] = { title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!", objectives = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8427] = { title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!", objectives = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
